parameters.url:
={{
  'https://api.github.com/repos/tech-reok/Incident-Remediation-Agent/contents/' +
  $fromAI(
    'path',
    'Exact repository file path to read. WARNING: You MUST have verified this exact path exists using the List files tool first. Do NOT guess or fabricate paths. Example: src/api/index.js',
    'string'
  ) +
  '?ref=' + ($('Prepare Branch').item.json.branch).trim()
}}

