parameters.jsonBody:
={{
  JSON.stringify({
    message: $fromAI(
      'commit_message',
      'Short git commit message describing this file change',
      'string'
    ),

    content: $fromAI(
      'content',
      'Complete new contents of the file in plain UTF-8 text. Do not Base64 encode it.',
      'string'
    ).base64Encode(),

    sha: $fromAI(
      'sha',
      'Exact current SHA of this file returned by the read-file tool',
      'string'
    ),

    branch: $('Prepare Branch').item.json.branch.trim()
  })
}}
